import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Long> A = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            A.add(sc.nextLong());
        }
        sc.close();

        long[] up = new long[n];
        long[] down = new long[n];

        up[0] = 1;
        for (int i = 1; i < n; i++) {
            if (A.get(i) > A.get(i - 1)) {
                up[i] = up[i - 1] + 1;
            } else {
                up[i] = 1;
            }
        }

        down[n - 1] = 1;
        for (int i = n - 2; i >= 0; i--) {
            if (A.get(i) > A.get(i + 1)) {
                down[i] = down[i + 1] + 1;
            } else {
                down[i] = 1;
            }
        }

        long maxPyramidSize = 0;
        for (int i = 0; i < n; i++) {
            long pyramidSize = 2 * Math.min(up[i], down[i]) - 1;
            if (pyramidSize > maxPyramidSize) {
                maxPyramidSize = pyramidSize;
            }
        }

        System.out.print(maxPyramidSize);
    }
}
